code='''def transform(grid):
    from collections import deque
    g=[r[:] for r in grid]; H=len(g); W=len(g[0])
    # Each non-background color seeds a rectangular zero canvas; use bounds of its 4-connected region of non-8 cells.
    seen=set()
    for i in range(H):
      for j in range(W):
        if g[i][j]==8 or (i,j) in seen: continue
        q=[(i,j)]; seen.add((i,j)); pts=[]
        for x,y in q:
          pts.append((x,y))
          for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
            if 0<=a<H and 0<=b<W and g[a][b]!=8 and (a,b) not in seen:
              seen.add((a,b)); q.append((a,b))
        colors={g[x][y] for x,y in pts if g[x][y] not in (0,8)}
        if not colors: continue
        r0=min(x for x,y in pts); r1=max(x for x,y in pts); c0=min(y for x,y in pts); c1=max(y for x,y in pts)
        for col in colors:
          cells=[(x,y) for x,y in pts if g[x][y]==col]
          a=min(x for x,y in cells); b=min(y for x,y in cells); ah=max(x for x,y in cells); bh=max(y for x,y in cells)
          th=ah-a+1; tw=bh-b+1
          pat=[[g[a+u][b+v] for v in range(tw)] for u in range(th)]
          for x in range(r0,r1+1):
            for y in range(c0,c1+1):
              if g[x][y]==0 and pat[(x-a)%th][(y-b)%tw]==col: g[x][y]=col
    return g
'''
